        let min_post = map_min_value(post.local_versions, (post.num_replicas - 1) as nat);
        assert(post.tail == pre.tail);
        assert(post.alive_bits === pre.alive_bits);
        assert(post.contents === pre.contents);
        assert forall |n| 0 <= n < pre.num_replicas implies min_pre <= post.local_versions[n] by {
            map_min_value_smallest(pre.local_versions, (pre.num_replicas - 1) as nat);
            if n == node_id { assert(pre.local_versions[n] <= post.local_versions[n]); }
            else { assert(pre.local_versions[n] == post.local_versions[n]); }
        }
        map_min_value_lower_bound(post.local_versions, (post.num_replicas - 1) as nat, min_pre);
        assert(min_pre <= min_post);
        assert forall |i: int| post.tail <= i < min_post + post.buffer_size
            implies !log_entry_is_alive(post.alive_bits, i, post.buffer_size) by {
            if (i < min_pre + post.buffer_size) {
                assert(pre.tail <= i < min_pre + pre.buffer_size);
                assert(!log_entry_is_alive(pre.alive_bits, i, pre.buffer_size));
            } else {
                let j = i - pre.buffer_size;
                assert(j >= min_pre);
                assert(j < min_post);
                assert(!log_entry_is_alive(pre.alive_bits, i, pre.buffer_size));
            }
