                <==> post.contents.contains_key(i)) by {
            assert(pre.tail - pre.buffer_size <= i < pre.tail);
            assert((log_entry_is_alive(pre.alive_bits, i, pre.buffer_size) || i < min_pre)
                <==> pre.contents.contains_key(i));
        }
    }

